package com.github.catvod.utils;import java.util.concurrent.*;import java.util.function.*;import com.google.common.util.concurrent.*;public class Task {public static <T> ListenableFuture<T> submit(Callable<T> task,long timeout){SettableFuture<T> f=SettableFuture.create();try{f.set(task.call());}catch(Throwable e){f.setException(e);}return f;}public static <T> FutureCallback<T> callback(Consumer<T> ok,Consumer<Throwable> fail){return new FutureCallback<T>(){public void onSuccess(T v){ok.accept(v);}public void onFailure(Throwable e){fail.accept(e);}};}}
